package pe.edu.cacaoselva.infrastructure.http;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import pe.edu.cacaoselva.application.port.*; import java.io.IOException; import java.net.URI; import java.net.http.*; import java.util.List;
public class HttpLoteQueryAdapter implements LoteQueryPort { private final HttpClient httpClient; private final URI endpoint; private final ObjectMapper objectMapper; public HttpLoteQueryAdapter(HttpClient httpClient,URI endpoint){this(httpClient,endpoint,new ObjectMapper());} public HttpLoteQueryAdapter(HttpClient httpClient,URI endpoint,ObjectMapper objectMapper){this.httpClient=httpClient;this.endpoint=endpoint;this.objectMapper=objectMapper;} public List<LoteDto> obtenerLotes(){HttpRequest request=HttpRequest.newBuilder(endpoint).GET().build(); try{HttpResponse<String> response=httpClient.send(request,HttpResponse.BodyHandlers.ofString()); if(response.statusCode()!=200) throw new ApiNoDisponibleException("La API respondió HTTP "+response.statusCode()); return objectMapper.readValue(response.body(),new TypeReference<>(){});}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new ApiNoDisponibleException("La consulta a la API fue interrumpida.",ex);}catch(IOException ex){throw new ApiNoDisponibleException("No se pudo conectar con la API.",ex);}} public static class ApiNoDisponibleException extends RuntimeException {public ApiNoDisponibleException(String message){super(message);} public ApiNoDisponibleException(String message,Throwable cause){super(message,cause);}} }
